style.css:
@-moz-document domain("fanfiction.net"), domain("m.fanfiction.net"), domain("fictionpress.com"), domain("m.fictionpress.com") {
/* ---- Palette ---------------------------------------------------------- */
  :root {
    color-scheme: dark;
    --ff-bg: #14181d;
    --ff-surface: #1c2128;
    --ff-surface-2: #1a1f26;
    --ff-header: #0d1117;
    --ff-border: #262c33;
    --ff-border-2: #2d333b;
    --ff-text: #e6edf3;
    --ff-body: #c4cdd6;
    --ff-muted: #9aa5b1;
    --ff-link: #5fb0e6;
    --ff-link-hover: #9bd4ff;
    --ff-green: #3fb950;
    /* brand accents refined for dark: FFN navy → readable blue-slate; FP maroon handled below */
    --ff-brand: #243b66;
  }

  /* ---- Base ------------------------------------------------------------- */
  html, body {
    background: var(--ff-bg) !important;
    color: var(--ff-body) !important;
  }

  /* Soften every light border into a subtle dark line */
  * {
    border-color: var(--ff-border) !important;
  }

  /* Bootstrap draws .caret as a pure-CSS triangle: one coloured border side and
     the other three `transparent`. The blanket reset above paints all four, so
     every nav / button / chapter-select caret renders as a solid rectangle. */
  .caret {
    border-top-color: var(--ff-muted) !important;
    border-right-color: transparent !important;
    border-bottom-color: transparent !important;
    border-left-color: transparent !important;
  }
  /* the story-actions menu opens upward: its triangle is drawn on border-bottom */
  .dropup .caret,
  .navbar-fixed-bottom .dropdown .caret {
    border-top-color: transparent !important;
    border-bottom-color: var(--ff-muted) !important;
  }

  /* FFN underlines story titles with a 1px #357BD6 rule (border-bottom, not
     text-decoration), which the blanket reset above flattens into the page line
     colour. Restore the accent so titles read as links again. */
  .stitle,
  .novtitle {
    border-bottom-color: var(--ff-link) !important;
  }
  /* Same #357BD6 rule, two more places the blanket reset reaches: `a:hover`
     pairs `text-decoration:none` with that border, so the underline IS the
     hover affordance for every link on the site, and `.underline` is the
     utility-class form. */
  a:hover,
  .underline {
    border-bottom-color: var(--ff-link) !important;
  }
  /* a tab owns its own border box: the site's `.nav-tabs > li > a:hover` outranks
     its global a:hover, so a hovered tab must not pick up the link accent */
  .nav-tabs > li > a:hover {
    border-bottom-color: var(--ff-border) !important;
  }

  /* ---- Divider rules ---------------------------------------------------- */
  /* FFN draws <hr> with border-style:none and a white→#cbcbcb→white gradient as
     its background, so the border-color reset above cannot reach it. */
  hr {
    background-color: var(--ff-border-2) !important;
    background-image: none !important;
  }
  /* The rule behind a section heading is painted by .lc-wrapper::after, and `*`
     never matches pseudo-elements — its #cdcdcd border-top survives untouched. */
  .lc-wrapper::after {
    border-top-color: var(--ff-border-2) !important;
  }
  /* .lc-left / .lc-right are the opaque white pills that mask the rule behind
     the heading text (breadcrumbs, reader toolbar, forum headers). */
  .lc-left,
  .lc-right {
    background-color: var(--ff-surface) !important;
  }
  /* Bootstrap separator inside the nav dropdowns */
  .dropdown-menu .divider {
    background-color: var(--ff-border-2) !important;
  }

  /* ---- Main content surfaces ------------------------------------------- */
  #content_wrapper,
  #content_wrapper_inner,
  #content_parent,
  .zui,
  /* FFN emits its status panels from a per-page inline <style>, never from
     xss26.css, as five identically-painted classes (#f6f7ee paper, #000 ink,
     `border: 1px outset`). All five must be listed: `.panel_normal` carries the
     "Message Type" notices (dead topic / user / review), `.panel_warning` the
     "Story Not Found" page on both hosts. */
  .panel_normal,
  .panel_warning,
  .panel_error,
  .panel_success,
  .panel_plain,
  .lc,
  .lc-wrapper,
  .lc-lg,
  .lc-md,
  .lc-sm,
  .gui_normal,
  .gui_table,
  .goog-rtopics,
  .table-striped,
  .zmenu {
    background-color: var(--ff-surface) !important;
    color: var(--ff-body) !important;
  }

  #content_wrapper {
    box-shadow: none !important;
  }

  /* keep nested transparent wrappers transparent so we don't stack surfaces */
  .lc-wrapper,
  #content_wrapper_inner,
  #content_parent {
    background-color: transparent !important;
  }
  /* The reader's Fontastic Panel "READING Texture" picker writes an inline
     `background: url(/static/textures/<name>.png) repeat` onto
     #content_wrapper_inner (guest-reachable: the choice rides in the xcookie2
     `read_light_texture` field and replays on every load). It is a paper
     background-IMAGE, so the transparent background-COLOR above does not clear
     it and the whole reader column renders bright under the light body text.
     FFN's own dark reading mode clears this background, so nothing is lost. */
  #content_wrapper_inner {
    background-image: none !important;
  }
  /* The panel's own live preview pane takes that same inline texture url() the
     moment a swatch is clicked, so the sample text renders --ff-body on cream
     paper (~1.3:1) while the reader behind it is correctly dark. */
  #_fontastic_reading_preview {
    background-image: none !important;
    background-color: var(--ff-surface-2) !important;
  }

  /* The "Narrow Results" rail on the writer / forum / community search results
     is a bare <div> with no class or id — its only paint is an inline
     `background-color:#ffffff` beside a `z-index:20000` float. Nothing else on
     FFN writes that literal (the page wrappers use `background-color: white`),
     so the substring is an exact hook. Without it the rail renders as a white
     column and its `<small>Narrow Results</small>` heading sits at ~1.7:1. */
  div[style*="background-color:#ffffff"] {
    background-color: var(--ff-surface) !important;
  }

  /* ---- Header / top brand bar ------------------------------------------ */
  /* FFN navy + FP maroon raw bars refined to harmonize with the dark palette.
     Every selector here is qualified with `div` on purpose: on m.fanfiction.net
     and m.fictionpress.com the id lives on <body id="top">, so a bare `#top`
     repaints the whole mobile page and turns every link into header text. */
  div#top {
    background-color: var(--ff-header) !important;
    border-bottom: 1px solid var(--ff-border-2) !important;
  }
  /* Mobile (m.fanfiction.net / m.fictionpress.com) top nav bar paints a
     white→grey linear-gradient background-image (bg-color transparent) — the
     already-light nav labels sit invisibly on it, and the bg-color audit is
     blind to the gradient. Kill the gradient, give it the dark header bg. */
  .t_head {
    background-image: none !important;
    background-color: var(--ff-header) !important;
    border-bottom: 1px solid var(--ff-border-2) !important;
  }
  /* the mobile nav labels are header chrome (natively black, not link blue) */
  .t_head a {
    color: var(--ff-text) !important;
  }
  .t_head a:hover {
    color: var(--ff-link-hover) !important;
  }
  div#top a,
  div#top .icon-fictionpress,
  #name_login,
  #name_login a {
    color: var(--ff-text) !important;
  }
  /* Login / Sign Up pills in the header keep an accent so they stand out */
  div#top .btn,
  #name_login .btn {
    background-color: var(--ff-brand) !important;
    color: var(--ff-text) !important;
    border-color: var(--ff-border-2) !important;
  }
  div#top .btn:hover,
  #name_login .btn:hover {
    background-color: #2d4a80 !important;
  }

  /* ---- Navigation menus / dropdowns ------------------------------------ */
  #nav_internal,
  #nav_internal a,
  .menulink,
  .xmenu_item,
  .dropdown,
  .dropdown > a,
  .dropdown-toggle {
    color: var(--ff-text) !important;
  }

  .dropdown-menu,
  ul.dropdown-menu,
  .open > .dropdown-menu {
    background-color: var(--ff-surface) !important;
    border: 1px solid var(--ff-border-2) !important;
    box-shadow: 0 6px 18px rgba(0,0,0,.5) !important;
  }
  .dropdown-menu li > a,
  .dropdown-menu a {
    color: var(--ff-body) !important;
  }
  /* Bootstrap 2 paints the highlight as a background-IMAGE gradient (#5678B2 →
     #5670B2) layered over its background-color, so our background-color never
     shows: the item renders the site's light blue under our dimmed --ff-text at
     3.9:1, where the site's own #fff cleared 4.6:1. Kill the gradient so the fill
     below is the one that paints. (`.active` is the same gradient trick in
     #0081c2; it does not render logged-out but shares the rule.) */
  .dropdown-menu li > a:hover,
  .dropdown-menu a:hover,
  .dropdown-menu > .active > a {
    background-color: var(--ff-brand) !important;
    background-image: none !important;
    color: var(--ff-text) !important;
  }
  /* Each nav dropdown heads its groups with a `li.disabled > a` label ("Stories",
     "Crossovers"): the site dims it to #999 against #333 entries and gives it no
     hover fill, which is the only cue that it is a heading and not a link. Both
     generic rules above outrank that, so headings read as entries and light up
     under the cursor. */
  .dropdown-menu > .disabled > a,
  .dropdown-menu > .disabled > a:hover,
  .dropdown-menu > .disabled > a:focus {
    color: var(--ff-muted) !important;
    background-color: transparent !important;
    background-image: none !important;
  }

  /* sub-nav grey links (Stories / Crossovers / All / Specific) */
  .menulink,
  #content_wrapper a[style*="color:#999"],
  .menulink a {
    color: var(--ff-muted) !important;
  }

  /* ---- Links ------------------------------------------------------------ */
  a {
    color: var(--ff-link) !important;
  }
  a:hover {
    color: var(--ff-link-hover) !important;
  }
  /* keep header / nav links from inheriting the body link blue where set above */
  div#top a:hover {
    color: var(--ff-link-hover) !important;
  }

  /* The general text rules below carry a class (.xcontrast_txt) or an element
     name (b) that outranks the bare `a` above, so FFN's breadcrumbs, author
     names, rating links and the bolded keyword runs in search-result titles all
     lose their link colour. Re-assert it on anchors and on runs inside one. */
  a.xcontrast_txt,
  #profile_top a,
  #profile_top a.xcontrast_txt,
  a b,
  a strong {
    color: var(--ff-link) !important;
  }
  a.xcontrast_txt:hover,
  #profile_top a:hover,
  #profile_top a.xcontrast_txt:hover,
  a:hover b,
  a:hover strong {
    color: var(--ff-link-hover) !important;
  }
  /* The forum post-admin row (opened by the cog beside a post) is the one place
     FFN puts an entry's LABEL inside the anchor's glyph span instead of in the
     anchor itself, so the blanket `span` rule below strips the link colour from
     `Report Abuse` while every sibling entry beside it stays blue. Its glyph
     siblings (`.icon-reply`, `.icon-cog`, `.icon-lock`) carry an inline
     `color:black` and must keep the body tone they get today. */
  a span.icon-cr-warning {
    color: var(--ff-link) !important;
  }
  a:hover span.icon-cr-warning {
    color: var(--ff-link-hover) !important;
  }
  /* Every muted metadata block — `.xgray` story-row lines on the desktop hosts,
     `.gray` listing lines on the m. hosts — ends in bare `<span data-xutime>` date
     children that carry no colour of their own and inherit the block's grey. The
     blanket `span { color }` rule below is a DIRECT declaration, so it beats that
     inheritance and lights only the dates up, inventing an emphasis the site never
     had. Keep this ABOVE the `span._thread` / brand-glyph rules that follow: they
     tie it on specificity, so order is what lets them win. */
  .xgray span,
  .gray span,
  .z-list .z-padtop2 span {
    color: var(--ff-muted) !important;
  }

  /* forum topic rows carry a clickable "jump to latest post" chevron painted
     #0033cc — a plain <span> wrapping the glyph <span>, so the body-text rule
     below greys out both */
  span._thread,
  span._thread span {
    color: var(--ff-link) !important;
  }
  span._thread:hover,
  span._thread:hover span {
    color: var(--ff-link-hover) !important;
  }
  /* Every story row ends with an orange `.reviews` link (#f50) — the site's only
     cue that it leads to the review list rather than to the story. The bare `a`
     rule above outranks the site's `.reviews` colour and the `a:hover` rule
     outranks it again on hover, so both states read as an ordinary blue link.
     #f50 clears 4.5:1 on the card surface; keep it verbatim. `.z-list a` below
     ties `a.reviews` on specificity and comes later, so the row form needs the
     `.z-list` prefix to win. */
  a.reviews,
  a.reviews:hover,
  .reviews,
  .z-list a.reviews,
  .z-list a.reviews:hover {
    color: #ff5500 !important;
  }

  /* Two fontello glyphs get their brand hue from an inline style attribute, and
     the blanket `span` rule below beats it. The crossover blue is lifted out of
     the 2:1 range it would land in on the dark surface. */
  span.icon-rss-squared {
    color: #ff8f00 !important;
  }
  span.icon-shuffle {
    color: #6d86f0 !important;
  }
  /* Two more glyphs the blanket `span` rule promotes to full body ink, both of
     which FFN keeps a step UNDER its body copy: the section chevron beside every
     breadcrumb and story title (`.xicon-section-arrow`, #5a5a5a in the site CSS)
     and the footer X/Twitter mark (inline #686464). Both source values are
     unreadable on the dark surface, so the muted tone is what carries the step. */
  span.xicon-section-arrow,
  span.icon-twitter-3 {
    color: var(--ff-muted) !important;
  }

  /* ---- Headings & general text ----------------------------------------- */
  h1, h2, h3, h4, h5, h6, b, strong {
    color: var(--ff-text) !important;
  }
  .xcontrast_txt,
  .xgray,
  td, th, p, span, div, li, label, dt, dd {
    color: var(--ff-body) !important;
  }
  .xgray, .gray, small {
    color: var(--ff-muted) !important;
  }
  /* `small` covers two unrelated things on FFN. Inside a table cell it is forum
     fine print (post dates, natively #686868) and belongs on the muted tone; as a
     direct child of a div it is the "Narrow Results" rail heading on /search/ and
     /betareaders/ (natively #000, the strongest ink in that panel) and the header
     separator pipe (natively #fff). Muting those two puts a heading below the
     controls it labels. */
  div > small {
    color: var(--ff-body) !important;
  }
  /* FFN writes its fine print as an inline grey one step under the black body copy:
     `color:gray` (the profile Sort bar, the sign-up disclaimer), `#8c8c8c` (the bio
     toggle), `#c4c4c4` (the footer ray id). The blanket text rule above is a direct
     declaration and outranks every one of them, which on the Sort bar puts the inert
     `Sort:` label ABOVE the `.gray` options it labels.
     The substring also matches an inline `background-color:` of the same value — FFN
     ships none, and this rule only sets `color`, so a stray match costs nothing. Keep a
     literal `;` OUT of these selectors: `parse-check.js` finds a rule's prelude by
     scanning back to the previous `;`, and reports a valid rule as dead.
     Anchors stay out on purpose: the disclaimer greys its links too, and those keep the
     link accent. */
  div[style*="color:gray"],
  span[style*="color:gray"],
  span[style*="color:#8c8c8c"],
  div[style*="color:#c4c4c4"] {
    color: var(--ff-muted) !important;
  }

  /* ---- Story list rows (browse / search results) ----------------------- */
  .z-list,
  .z-list-content {
    background-color: var(--ff-surface) !important;
    border-bottom: 1px solid var(--ff-border) !important;
  }
  .z-list:hover {
    background-color: var(--ff-surface-2) !important;
  }
  .z-list a,
  .z-list .stitle {
    color: var(--ff-link) !important;
  }
  /* Every story row stacks a summary (#000 natively) over a `.z-padtop2.xgray`
     metadata line (#686868) — the site's only ranking of the two. Promoting the
     metadata to body text collapses them into one block of identical grey on every
     browse / search / profile / community / review page. --ff-muted keeps the step
     and still clears 6.4:1 on the row surface. */
  .z-list .xgray,
  .z-list .z-padtop2 {
    color: var(--ff-muted) !important;
  }

  /* ---- Story reader (#storytext core long-text surface) ---------------- */
  /* The m. hosts name the story column #storycontent (desktop: #storytext), and
     their reader footer's "Contrast: Dark . Light" control writes the pick straight
     onto it: `x_contrast()` sets an inline `background-color:white` (Light) or
     `#333` (Dark), and `x_render_s_pref()` replays the dark one on reload as a
     document.write'd sheet declaring `background-color:#333` on `.storycontent`.
     The blanket text rule below keeps our light body ink under either, so one guest
     click leaves the whole column light-grey on white. Both forms are background
     declarations, so clearing the background covers them. */
  #storytext,
  #storytextp,
  .storytext,
  #storycontent,
  .storycontent {
    color: var(--ff-body) !important;
    background-color: transparent !important;
  }
  /* do NOT force a single color on inner runs — preserve author bold/italic/
     alignment/hr emphasis; only normalize the common black text default */
  #storytext p,
  #storytext div,
  #storytext span[style*="color: rgb(0, 0, 0)"],
  #storytext font[color="#000000"],
  #storytext font[color="black"] {
    color: var(--ff-body) !important;
  }
  #storytext hr {
    border-color: var(--ff-border-2) !important;
  }

  /* story info box on the chapter page */
  #profile_top {
    background-color: var(--ff-surface) !important;
    border: 1px solid var(--ff-border) !important;
    color: var(--ff-body) !important;
  }
  #profile_top b,
  #profile_top .xcontrast_txt {
    color: var(--ff-text) !important;
  }
  /* The metadata line under the summary is `<span class="xgray xcontrast_txt">`
     (#686868 natively, a step BELOW the black summary). The rule above matches it on
     `.xcontrast_txt` at (1,1,0), so the dimmest run in the box came out as the
     brightest — the site's hierarchy inverted. */
  #profile_top .xgray.xcontrast_txt,
  #profile_top .xgray {
    color: var(--ff-muted) !important;
  }

  /* ---- Reading-options bar + chapter select ---------------------------- */
  select,
  select[name="chapter"],
  #chap_select {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
    border: 1px solid var(--ff-border-2) !important;
  }
  select option {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
  }
  /* The search page's "Narrow Results" rails are `<select size="7">` list boxes whose
     rows are always visible, so the UA highlight on the clicked row is the only
     acknowledgement a filter was picked. The blanket option fill above outranks it and
     the row stays identical to its siblings. */
  select[size] option:checked {
    background-color: var(--ff-brand) !important;
    color: var(--ff-text) !important;
  }
  /* FFN marks every filter dropdown that carries a non-default value with
     .selection_hl (green border + pale-green fill) — that is the only cue for
     "this filter is active". The generic select rule above and the blanket
     `* { border-color }` reset both outrank it, so a set filter looked exactly
     like an unset one. Restore the cue as a dark green-tinted field. */
  select.selection_hl {
    background-color: rgba(63, 185, 80, .18) !important;
    border-color: var(--ff-green) !important;
    color: var(--ff-text) !important;
  }

  /* ---- Browse filter bar buttons / segmented controls / sort tabs ------ */
  button,
  .btn,
  input[type="button"],
  input[type="submit"],
  input[type="reset"] {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
    border: 1px solid var(--ff-border-2) !important;
    background-image: none !important;
    text-shadow: none !important;
  }
  button:hover,
  .btn:hover {
    background-color: #232a32 !important;
    color: var(--ff-text) !important;
  }
  /* Bootstrap marks the toggle of an OPEN dropdown/dropup by dropping the
     white→grey gradient for the flat `#e6e6e6` it also uses for `:hover` and
     `.active` — the only pressed cue on the button itself. The `.btn` fill
     above is `!important` and outranks it, so an open toggle rendered
     identical to its closed siblings on the reader's Actions / Share / review
     "As" menus and the search-type picker. Same tone as the hover arm, which
     is what the site does. */
  .btn-group.open .btn.dropdown-toggle {
    background-color: #232a32 !important;
  }
  .btn.active,
  .btn-primary,
  .active > .btn {
    background-color: var(--ff-brand) !important;
    color: var(--ff-text) !important;
  }
  /* The category-picker popup (`/search/?popup=1`, opened by the "Select" link
     in the search Options panel) ships its submit as a real
     `<input type="button" disabled>` until a main category is picked. The UA
     paints a disabled control at 30% ink; the rules above are `!important` and
     repaint it at full strength, so a dead control reads as clickable. Must
     stay AFTER the hover/active arms — it ties them on specificity and only
     wins on order. */
  button[disabled],
  input[disabled],
  select[disabled],
  textarea[disabled],
  .btn.disabled {
    background-color: var(--ff-bg) !important;
    color: var(--ff-muted) !important;
    border-color: var(--ff-border) !important;
    opacity: .7 !important;
  }

  /* ---- Form inputs & search -------------------------------------------- */
  input[type="text"],
  input[type="search"],
  input[type="email"],
  input[type="password"],
  input:not([type]),
  textarea {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
    border: 1px solid var(--ff-border-2) !important;
  }
  ::placeholder {
    color: var(--ff-muted) !important;
    opacity: 1 !important;
  }

  /* ---- Tables (gui_table, forum topic lists, .table-striped) ----------- */
  /* FFN forums render rows as a striped table whose <td> carry their own
     light bg (rgb(249,249,249)); target the cells directly, not just rows. */
  .gui_table,
  .gui_table td,
  .gui_table th,
  .tcat,
  table.table,
  table.table td,
  table.table th,
  .table-striped td,
  .table-striped th,
  .table-striped > tbody > tr:nth-of-type(odd) > td,
  .table-bordered {
    background-color: var(--ff-surface) !important;
    color: var(--ff-body) !important;
    border-color: var(--ff-border) !important;
  }
  .tcat,
  thead th {
    background-color: var(--ff-header) !important;
    color: var(--ff-text) !important;
  }
  /* Forum boards label their columns with `<th class="thead">`, which the site dims
     to grey against the black rows — the only thing that reads the row as a header,
     since its background matches the body rows. `table.table th` above is (0,1,2) and
     outranks both `.thead` and the `thead th` arm, so the labels came out as content. */
  table.table th.thead,
  th.thead {
    color: var(--ff-muted) !important;
  }
  .table-striped > tbody > tr:nth-of-type(even) > td {
    background-color: var(--ff-surface-2) !important;
  }
  tr:hover > td {
    background-color: var(--ff-surface-2) !important;
  }

  /* ---- Forum post quotes ----------------------------------------------- */
  /* FFN styles quoted text with color:#535353 — readable on the old light
     posts, dark-on-dark here. Lift to body text, keep the quote accent bar. */
  blockquote,
  blockquote.quoteStyle,
  .quoteStyle {
    color: var(--ff-body) !important;
    border-color: var(--ff-border-2) !important;
  }

  /* ---- Highlight spans (.hiliteStyle) ---------------------------------- */
  /* FFN highlights forum "(N posts)" counts and matched search terms with a
     pale-green mark (bg #ccffcc, dark text). As a short inline pill it slips
     the height-based light-surface audit, and our body-text rule leaves its
     text light-grey → washed-out on the pale green. Swap to a dark green-
     tinted mark that keeps the highlight cue with readable light text. */
  .hiliteStyle {
    background-color: rgba(63, 185, 80, .2) !important;
    color: var(--ff-text) !important;
  }

  /* ---- Badges / counters ----------------------------------------------- */
  /* default grey badge → dark chip with readable light text */
  .badge {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-text) !important;
    border: 1px solid var(--ff-border-2) !important;
    text-shadow: none !important;
  }
  .badge-blue {
    background-color: var(--ff-brand) !important;
    color: var(--ff-text) !important;
  }
  /* The site distinguishes the selected/hovered forum topic-filter chip with a
     plain .badge-active / .badge:hover (no !important), which our generic
     .badge rule above outranks — both states collapse into the default chip.
     Re-establish them so the active filter reads as selected. */
  .badge:hover {
    background-color: #232a32 !important;
  }
  .badge-active,
  .badge-active:hover {
    background-color: var(--ff-brand) !important;
    border-color: var(--ff-brand) !important;
    color: var(--ff-text) !important;
  }

  /* The join-date pill beside every beta reader / community member is
     .xcount (#e1e1e1 bg with #626262 text). Only ~14px tall, so the
     height-based light-surface audit skips it, and the body-text rule leaves
     its label light-grey on light-grey — a bright pill with unreadable text. */
  .xcount {
    background-color: var(--ff-surface-2) !important;
    color: var(--ff-muted) !important;
    border: 1px solid var(--ff-border-2) !important;
  }
  .xcount:hover {
    background-color: #232a32 !important;
    color: var(--ff-text) !important;
  }

  /* ---- Profile / story tabs (Bootstrap .nav-tabs) ---------------------- */
  /* FFN renders the active tab (li.active > a) with a white "folder" bg meant
     to sit on light content — paints a bright panel on dark. As a short 38px
     pill it slips past the height-based light-surface audit.
     Selection lives on `li.active` ONLY: `a.current` is an inert marker the
     site never styles and its tab-switch JS never moves, so keying off it
     leaves the first tab looking selected alongside the real one. */
  .nav-tabs > li > a,
  .nav-tabs a {
    background-color: transparent !important;
    color: var(--ff-link) !important;
  }
  /* Bootstrap gives an inactive tab `border: 1px solid transparent`, so only the
     selected tab draws the folder outline — and that outline is the whole cue, since
     the active tab's fill matches the panel behind it on FFN as it does natively.
     The blanket `* { border-color }` reset paints all four sides of every tab, so each
     one renders as a closed box and selection collapses to the label colour alone. */
  .nav-tabs > li > a {
    border-color: transparent !important;
  }
  .nav-tabs > li.active > a,
  .nav-tabs > .active > a:hover,
  .nav-tabs > .active > a:focus {
    background-color: var(--ff-surface) !important;
    color: var(--ff-text) !important;
    border-color: var(--ff-border-2) !important;
    border-bottom-color: var(--ff-surface) !important;
  }
  /* native hover restores an outline (`border-color: #eee #eee #ddd`), so the tab under
     the cursor must box up again — otherwise the transparent rule above eats the
     hover affordance the site draws. Bottom stays the line colour, not the link accent. */
  .nav-tabs > li > a:hover {
    background-color: var(--ff-surface-2) !important;
    border-color: var(--ff-border-2) var(--ff-border-2) var(--ff-border) !important;
  }

  /* ---- Advanced-filter modal ------------------------------------------- */
  .modal,
  .modal-body,
  .modal-header,
  .modal-footer,
  .modal-content,
  #filters {
    background-color: var(--ff-surface) !important;
    color: var(--ff-body) !important;
    border-color: var(--ff-border-2) !important;
  }
  /* Bootstrap paints a white inset highlight along the footer's top edge; a
     box-shadow is invisible to every background-color audit. */
  .modal-footer,
  .modal-header {
    box-shadow: none !important;
  }

  /* ---- Semantic cues: keep status / completed green readable ----------- */
  /* FFN uses dark greens (e.g. #04761c "Complete"/"Plus") that vanish on
     dark; lift them to the palette green while keeping the semantic. */
  span[style*="color:green"],
  span[style*="#04761c"],
  span[style*="#080"],
  .status_complete,
  font[color="green"] {
    color: var(--ff-green) !important;
  }
  /* The Filters modal pairs a green "Plus" heading with a red "Without" one
     (inline style="color:#c00000") to mark the include vs exclude sections.
     The green survived via the rule above; the blanket span rule flattened the
     red to body text, so only half the cue was left. Lift it to a readable red
     — #c00000 sits at ~2.8:1 on the modal surface. */
  span[style*="#c00000"],
  span[style*="color:red"],
  font[color="red"] {
    color: #f85149 !important;
  }

  /* ---- Cookie bar ------------------------------------------------------- */
  /* Its Accept control is a bare <div> whose only affordance is an inline
     `border:1px whitesmoke solid`; the blanket border reset darkens it below
     the bar's own #363636 background, leaving an invisible click target. */
  #cookie_notice div[onclick] {
    border-color: var(--ff-muted) !important;
  }

  /* ---- Footer ----------------------------------------------------------- */
  #footer,
  .footer,
  #zfooter {
    background-color: var(--ff-header) !important;
    color: var(--ff-muted) !important;
    border-top: 1px solid var(--ff-border-2) !important;
  }
  #footer a, .footer a { color: var(--ff-link) !important; }

  /* ---- Ad slots: darken blank bright rectangles ------------------------ */
  ins.adsbygoogle,
  .adsbygoogle,
  div[id^="div-gpt-ad"],
  div[id*="_ad_"],
  div[id^="ad_"],
  .ad_slot,
  [id^="google_ads"],
  iframe[id^="google_ads"],
  iframe[id^="aswift"],
  .goog-rtopics,
  .goog-rentries,
  .goog-rentry,
  .google-anno,
  .google-anno-skip,
  .google-anno-sc {
    background-color: var(--ff-bg) !important;
  }

  /* ---- Misc: don't tint cover images ----------------------------------- */
  img, .cimage {
    background-color: transparent !important;
  }
  /* FFN serves ONE raster for every missing cover and every missing avatar:
     /static/images/d_60_90.jpg, a near-white plate (mean luminance 170/255)
     that repeats 13-26 times per browse row list, review list, forum thread,
     community index and beta list. Real cover art and real user avatars are
     served from /image/<id>/ and must stay untouched, so the correction is
     keyed to that one filename. No DOM scan reads image pixels, and the
     element itself is transparent, so every bucket passes on it. */
  img[src*="d_60_90"] {
    filter: brightness(.35) !important;
  }
  /* The m. hosts mark each story row with a 16px document raster —
     fcons/script-text.png (FictionPress) and fcons/script-attribute-c.png
     (FanFiction), up to 48 per Just In page. Roughly a third of their opaque
     pixels are pure white: the sheet of paper, invisible against the site's own
     white page and a glaring chip here. Inverting turns the paper into the row
     surface; the hue-rotate puts the coloured outline and letter back on their
     own hue. The other fcons/ficons rasters are coloured line art with no white
     plate (measured) and must not be filtered. */
  img[src*="fcons/script-"] {
    filter: invert(1) hue-rotate(180deg) !important;
  }
}
